<template><div class="measurement-workspace"><div class="measurement-workspace__list"><button type="button" @click="create">Neues Aufmaß</button><p v-if="error" class="error">{{ error }}</p><ul><li v-for="item in records" :key="item.id"><button :class="{active: selected?.id === item.id}" @click="open(item.id)">{{ item.title }} <small>{{ item.status }}</small></button></li></ul></div><div v-if="selected" class="measurement-workspace__editor"><header><h3>{{ selected.title }}</h3><small>v{{ selected.version }} · {{ selected.uuid }}</small></header><article v-for="block in blocks" :key="block.id" class="measurement-workspace__block"><div class="measurement-workspace__block-head"><strong>{{ labels[block.type] }}</strong><span><button @click="move(block,-1)" :disabled="block.position===1">↑</button><button @click="move(block,1)" :disabled="block.position===blocks.length">↓</button><button @click="remove(block)">Löschen</button></span></div><textarea v-if="block.type==='text'" v-model="block.payload.text" @change="save(block)" rows="3"/><div v-else-if="block.type==='measurement'" class="measure"><input v-model.number="block.payload.quantity" type="number" min="0" @change="save(block)"><input v-model="block.payload.unit" @change="save(block)"><input v-model="block.payload.label" placeholder="Bezeichnung" @change="save(block)"></div><MeasurementDrawing v-else-if="block.type==='drawing'" v-model="block.payload.strokes" @update:model-value="save(block)"/><a v-else :href="fileUrl(block.payload.assetFileId)" target="_blank" rel="noopener">Anhang öffnen ({{ block.payload.mimeType }})</a></article><div class="measurement-workspace__add"><button v-for="type in ['text','measurement','image','plan','drawing']" :key="type" @click="add(type)">+ {{ labels[type] }}</button><label>Datei für Bild/Plan <input type="file" accept="image/png,image/jpeg,application/pdf" @change="asset"></label></div></div><p v-else>Aufmaß auswählen oder neu anlegen.</p></div></template>
<script>
import { generateUrl } from '@nextcloud/router'
import MeasurementDrawing from './MeasurementDrawing.vue'
import { fetchMeasurementRecords, createMeasurementRecord, fetchMeasurementRecord, createMeasurementBlock, updateMeasurementBlock, deleteMeasurementBlock, reorderMeasurementBlocks, uploadMeasurementAsset } from '../services/measurementRecordsApi.js'
export default { name:'MeasurementWorkspace', components:{MeasurementDrawing}, props:{projectId:{type:[Number,String],required:true}}, data:()=>({records:[],selected:null,blocks:[],error:null,labels:{text:'Text',measurement:'Messwert',image:'Foto',plan:'Plan',drawing:'Zeichnung'}}), mounted(){this.load()}, methods:{ async load(){try{this.records=await fetchMeasurementRecords(this.projectId)}catch(e){this.fail(e)}}, async open(id){try{const data=await fetchMeasurementRecord(id);this.selected=data.record;this.blocks=data.blocks}catch(e){this.fail(e)}}, async create(){const title=window.prompt('Titel des Aufmaßes');if(!title)return;try{const record=await createMeasurementRecord(this.projectId,title);await this.load();await this.open(record.id)}catch(e){this.fail(e)}}, defaults(type){return {text:{text:''},measurement:{quantity:1,unit:'m'},drawing:{strokes:[]}}[type]}, async add(type){if(['image','plan'].includes(type)){this.error='Bitte zuerst eine Datei auswählen.';return}try{const block=await createMeasurementBlock(this.selected.id,type,this.defaults(type));this.blocks.push(block)}catch(e){this.fail(e)}}, async asset(event){const file=event.target.files?.[0];if(!file)return;try{const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});const ref=await uploadMeasurementAsset(this.projectId,content);const type=file.type==='application/pdf'?'plan':'image';this.blocks.push(await createMeasurementBlock(this.selected.id,type,ref))}catch(e){this.fail(e)}finally{event.target.value=''}}, async save(block){try{const updated=await updateMeasurementBlock(this.selected.id,block.id,block.payload);Object.assign(block,updated)}catch(e){this.fail(e)}}, async remove(block){try{await deleteMeasurementBlock(this.selected.id,block.id);this.blocks=this.blocks.filter(b=>b.id!==block.id)}catch(e){this.fail(e)}}, async move(block,by){const index=this.blocks.indexOf(block), target=index+by;if(target<0||target>=this.blocks.length)return;const reordered=[...this.blocks];[reordered[index],reordered[target]]=[reordered[target],reordered[index]];try{this.blocks=await reorderMeasurementBlocks(this.selected.id,reordered.map(b=>b.id))}catch(e){this.fail(e)}}, fileUrl(id){return generateUrl(`/f/${id}`)},fail(e){this.error=e?.response?.data?.ocs?.meta?.message??e.message??String(e)} } }
</script><style scoped>.measurement-workspace{display:grid;grid-template-columns:minmax(180px,260px) minmax(0,1fr);gap:20px}.measurement-workspace__list ul{padding:0;list-style:none}.measurement-workspace__list li button{width:100%;text-align:left;background:none;border:0;padding:8px}.measurement-workspace__list li button.active{background:var(--color-primary-element-light)}.measurement-workspace__block{border:1px solid var(--color-border);padding:12px;margin:10px 0;border-radius:var(--border-radius,4px)}.measurement-workspace__block-head{display:flex;justify-content:space-between}.measurement-workspace textarea,.measure input{width:100%;box-sizing:border-box}.measure{display:grid;grid-template-columns:1fr 80px 2fr;gap:8px}.measurement-workspace__add{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.error{color:var(--color-error-text,#c00)}@media(max-width:700px){.measurement-workspace{grid-template-columns:1fr}}</style>
